SELECT 'gongkao', '平均数增长率', 'kp-xingce-data-average-growth-rate', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "平均数增长率"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "资料分析中最特殊的终极杀器公式，专门用于求平均数的相对变化幅度。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目明确问：“2023年，某某的平均数（如均价、亩产、人均收入）比去年"}, {"type": "text", "text": "增长了百分之多少", "marks": [{"type": "bold"}, {"type": "textStyle", "color": "#ef4444"}]}, {"type": "text", "text": "？” 选项全是一堆带 % 的数字。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式（必背！）"}]}, {"type": "katexBlock", "attrs": {"content": "平均数增长率 = \\frac{a - b}{1 + b}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（其中：a 为分子增速，b 为分母增速）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到'均价增长率'等问法] --> B[立刻写出公式 (a-b)/(1+b)]\nB --> C[回材料定位分子增速a和分母增速b]\nC --> D[先算分子 a-b]\nD --> E{观察分母 1+b}\nE -- b 为正数 --> F[真实结果必定 略小于 a-b, 去选项秒杀]\nE -- b 为负数 --> G[真实结果必定 略大于 a-b, 去选项秒杀]\nE -- 选项极其接近 --> H[老老实实算完除法]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年商品房销售额增长 15%(a)，销售面积增长 5%(b)。求房屋均价的增长率？选项：A. 8.2% B. 9.5% C. 10.0% D. 11.5%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "明确指标：均价 = 销售额 / 面积。a=15%，b=5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列入公式：(15% - 5%) / (1 + 5%) = 10% / 1.05。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "神级估算：10% 除以一个大于 1 的数(1.05)，结果一定略小于 10%！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定选项：选项中略小于 10% 的只有 B (9.5%)。不需要动笔列竖式。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分母记错（最惨痛的代价）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在“基期比重”、“基期平均数”甚至“比重变化量”的所有公式里，分母都是 1+a（分子增速）。但唯独在这个公式里，分母是 1+b（分母增速）！记混了直接完蛋。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把这个公式写在便利贴上贴在屏幕边缘。每次考前看一眼。"}]}]}$$ AS jsonb), NULL, '平均数增长率的核心考点与实战推导。', category_node.id, CAST('["资料分析", "平均数增长率"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_average_growth_rate", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
